extends Resource
class_name ItemData

@export var id: String
@export var quantity: int
@export var rarity: int

extends Resource
class_name GameSaveData

@export var player_position: Vector2
@export var inventory: Array[ItemData] = []
@export var unlocked_levels: PackedStringArray
@export var last_played: int

extends RefCounted
class_name SaveManager

static func save_to_disk(data: GameSaveData, path: String, binary: bool) -> int:
	var target_path = path
	var ext = path.get_extension()
	if binary:
		if ext != "res":
			target_path = path.get_basename() + ".res"
	else:
		if ext != "tres":
			target_path = path.get_basename() + ".tres"
	return ResourceSaver.save(data, target_path)


static func load_from_disk(path: String) -> GameSaveData:
	var ext = path.get_extension()
	if ext == "res":
		if FileAccess.file_exists(path):
			return ResourceLoader.load(path) as GameSaveData
	elif ext == "tres":
		if FileAccess.file_exists(path):
			return ResourceLoader.load(path) as GameSaveData
	else:
		# No extension provided: prefer .tres then .res
		var base = path.get_basename()
		var tres = base + ".tres"
		if FileAccess.file_exists(tres):
			return ResourceLoader.load(tres) as GameSaveData
		var res = base + ".res"
		if FileAccess.file_exists(res):
			return ResourceLoader.load(res) as GameSaveData
	return null


static func compute_hash(data: GameSaveData) -> String:
	var ctx := HashingContext.new()
	ctx.start(HashingContext.HASH_SHA256)
	ctx.update(str(data.player_position).to_utf8_buffer())
	ctx.update(str(data.unlocked_levels).to_utf8_buffer())
	ctx.update(str(data.last_played).to_utf8_buffer())
	for item in data.inventory:
		ctx.update(str(item.id).to_utf8_buffer())
		ctx.update(str(item.quantity).to_utf8_buffer())
		ctx.update(str(item.rarity).to_utf8_buffer())
	var digest := ctx.finish()
	return digest.hex_encode().to_lower()

